// Nutrition Practice Test 1. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items: calculations, deficiency mechanisms and diet therapy decisions.
import {q, mix} from './q.js';
const ROTH='Roth, Nutrition and Diet Therapy', WEST='West, Nutrition and Wellness for Life';
const MAC='Carbohydrates, fats and proteins', VIT='Vitamins & minerals', WAT='Water (Fluid & electrolyte balance)', LIFE='Nutrition through the life span', DIG='Digestion, absorption, and metabolism', CULT='Cultural patterns and food habits', ILL='Food-related illnesses, intolerances, and allergies', MNT='Medical nutrition therapy';

export default {
 id:'nutrition-1',
 event:'Nutrition',
 title:'Practice Test 1',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Roth’s Nutrition and Diet Therapy and West’s Nutrition and Wellness for Life',
 plan:[{area:MAC,weight:15},{area:VIT,weight:15},{area:WAT,weight:10},{area:LIFE,weight:15},{area:DIG,weight:10},{area:CULT,weight:5},{area:ILL,weight:10},{area:MNT,weight:20}],
 questions:mix([
  q(MAC,'Rice and beans eaten together supply all the essential amino acids. What are they called?','Complementary proteins',['Complete proteins','Incomplete fats','Conditional amino acids'],'B','Each plant protein lacks some essential amino acids, but together they supply all nine. A complete protein, such as eggs, meat or soy, contains all of them on its own.',ROTH),
  q(MAC,'How does soluble fiber, such as the fiber in oats, help lower blood cholesterol?','It binds bile acids so the liver uses cholesterol to make more',['It blocks the liver from making any cholesterol','It speeds food through the colon too fast to absorb fat','It converts LDL cholesterol into HDL cholesterol'],'A','Soluble fiber traps bile acids in the gut so they are excreted. The liver then pulls cholesterol from the blood to make new bile, lowering LDL.',ROTH),
  q(MAC,'Why are trans fats considered the most harmful dietary fat for the heart?','They raise LDL and lower HDL cholesterol',['They raise HDL and lower triglycerides','They contain more calories per gram than other fats','They cannot be digested by the body'],'D','Trans fats, made by partially hydrogenating oils, raise “bad” LDL and lower “good” HDL, increasing heart disease risk more than saturated fat.',ROTH),
  q(MAC,'A snack contains 10 g of fat, 20 g of carbohydrate and 5 g of protein. How many calories does it provide?','190 kcal',['140 kcal','175 kcal','315 kcal'],'C','Fat = 9 kcal/g, carbohydrate and protein = 4 kcal/g each. (10 × 9) + (20 × 4) + (5 × 4) = 90 + 80 + 20 = 190 kcal.',ROTH),
  q(MAC,'Where does the body store glycogen?','In the liver and skeletal muscle',['In the pancreas and kidneys','In adipose tissue under the skin','In the blood plasma'],'A','Glycogen, the storage form of glucose, is kept in the liver (to maintain blood glucose) and in muscle (for the muscle’s own use).',ROTH),
  q(MAC,'When carbohydrate intake is very low, the body breaks down fat for energy and produces ketones. Why?','Fat cannot be fully metabolized without enough carbohydrate',['Ketones are needed to digest dietary protein','The liver turns excess protein directly into ketones','Low carbohydrate intake stops all insulin production'],'B','Without enough carbohydrate, fat metabolism is incomplete and ketone bodies build up (ketosis). This is why at least 50–100 g of carbohydrate a day is recommended to prevent ketosis.',ROTH),
  q(MAC,'Which food is the best source of omega-3 fatty acids?','Salmon',['Coconut oil','Butter','Beef liver'],'D','Fatty fish such as salmon, mackerel and sardines are rich in EPA and DHA, omega-3 fatty acids linked to lower inflammation and heart disease risk. Coconut oil and butter are mostly saturated fat.',WEST),
  q(MAC,'A child in a famine area has a swollen belly and edema despite thin arms, from a diet with some calories but very little protein. What is this condition?','Kwashiorkor',['Marasmus','Rickets','Pellagra'],'C','Kwashiorkor is protein deficiency with relatively adequate calories; low blood proteins let fluid leak into tissues, causing edema. Marasmus is a severe deficiency of both calories and protein, causing wasting.',ROTH),
  q(VIT,'Why are fat-soluble vitamins more likely than water-soluble vitamins to cause toxicity?','They are stored in the liver and fat tissue',['They are absorbed directly into the blood','They are made in large amounts by the body','They are excreted quickly in the urine'],'A','Vitamins A, D, E and K are stored in body fat and the liver, so excess intake from supplements can build up. Most excess water-soluble vitamins are excreted in urine.',ROTH),
  q(VIT,'A sailor on a long voyage develops bleeding gums, poor wound healing and tiny skin hemorrhages. Which vitamin is lacking?','Vitamin C',['Vitamin B12','Vitamin D','Vitamin A'],'B','Vitamin C is needed to make collagen. Without it, blood vessels and gums weaken, causing scurvy.',ROTH),
  q(VIT,'People with chronic alcohol use are at risk for Wernicke-Korsakoff syndrome because of a deficiency of which vitamin?','Thiamin (B1)',['Niacin (B3)','Riboflavin (B2)','Vitamin B6'],'D','Alcohol reduces thiamin intake and absorption. Thiamin deficiency causes beriberi and, in alcoholism, Wernicke-Korsakoff syndrome with confusion and memory loss.',ROTH),
  q(VIT,'Why should women who could become pregnant consume 400 mcg of folic acid daily?','To lower the risk of neural tube defects',['To prevent iron deficiency anemia in the newborn','To increase calcium stored in the fetal bones','To reduce nausea in the first trimester'],'C','The neural tube closes in the first month, often before a woman knows she is pregnant. Adequate folate before and during early pregnancy lowers the risk of spina bifida and anencephaly.',ROTH),
  q(VIT,'Rickets in children is caused by a deficiency of vitamin D because vitamin D is needed to:','Absorb calcium and phosphorus',['Form red blood cells in the bone marrow','Produce collagen in growing bones','Store glycogen in the muscles'],'A','Without vitamin D, the intestine absorbs too little calcium and phosphorus, so bones cannot mineralize and become soft and bowed.',ROTH),
  q(VIT,'A vegetarian wants to absorb more iron from beans and spinach. Which addition to the meal helps most?','Orange juice',['A cup of tea','A glass of milk','A calcium supplement'],'B','Vitamin C improves absorption of nonheme (plant) iron. Tea contains tannins and calcium competes with iron, both reducing absorption.',WEST),
  q(VIT,'Why are newborns given a vitamin K injection at birth?','Their gut lacks bacteria that make vitamin K',['Breast milk contains no fat to carry vitamin K','Their livers cannot store any vitamins','It prevents jaundice in the first week'],'D','Vitamin K is needed for clotting. Newborns have a sterile gut and low stores, so a single injection prevents vitamin K deficiency bleeding.',ROTH),
  q(WAT,'About what percentage of a healthy adult’s body weight is water?','50–60%',['20–30%','30–40%','75–85%'],'C','Water makes up roughly 50–60% of adult body weight, more in lean people and infants (about 75%) and less in older adults and people with more body fat.',ROTH),
  q(WAT,'Where is most of the body’s water located?','Inside the cells',['In the blood plasma','In the spaces between cells','In the lymphatic system'],'A','About two-thirds of body water is intracellular. The remaining third is extracellular, mostly in the spaces between cells, with a smaller amount in plasma.',ROTH),
  q(WAT,'Which electrolyte is the main cation in intracellular fluid?','Potassium',['Sodium','Chloride','Calcium'],'B','Potassium is the major positive ion inside cells, while sodium is the major positive ion outside cells. This difference is essential for nerve impulses and muscle contraction.',ROTH),
  q(WAT,'Why are older adults at greater risk of dehydration?','Their sense of thirst is weaker',['They need less water than younger adults','Their kidneys hold on to too much water','They lose less water through the skin'],'D','The thirst mechanism weakens with age and the kidneys concentrate urine less effectively, so older adults may not drink enough even when they need fluid.',ROTH),
  q(WAT,'A patient with severe liver disease has low blood albumin and swollen legs. How does low albumin cause edema?','Low blood protein lets fluid leak into tissues',['Albumin carries sodium out through the kidneys','Low albumin raises blood pressure in the arteries','Albumin is needed for the heart to pump fluid'],'C','Albumin creates oncotic pressure that holds fluid in the blood vessels. When it is low, fluid moves into the spaces between cells.',ROTH),
  q(LIFE,'What makes colostrum, the first breast milk, especially important for a newborn?','It is rich in antibodies that protect against infection',['It is higher in fat than mature breast milk','It contains all the iron needed for the first year','It replaces the need for vitamin K at birth'],'A','Colostrum is high in antibodies, protein and immune cells that protect the newborn’s gut and help establish healthy bacteria.',ROTH),
  q(LIFE,'Why should honey not be given to infants under 1 year old?','It may carry spores that cause botulism',['It causes tooth decay before teeth erupt','It is too high in fiber for infants','It triggers lactose intolerance in infants'],'B','Honey can contain Clostridium botulinum spores. An infant’s immature gut cannot prevent them from producing toxin.',ROTH),
  q(LIFE,'About how many extra calories per day does a woman need during the second trimester of pregnancy?','About 340 kcal',['About 100 kcal','About 1,000 kcal','No additional calories'],'D','No extra calories are needed in the first trimester; about 340 extra kcal/day are recommended in the second and about 450 in the third.',ROTH),
  q(LIFE,'Why is the recommended calcium intake highest during adolescence (1,300 mg/day)?','Bone mass is building rapidly during growth spurts',['Teenagers absorb calcium poorly from food','Calcium is needed to make adolescent hormones','Teens lose calcium through increased sweating'],'C','Most peak bone mass is built during adolescence. Getting enough calcium then lowers the risk of osteoporosis later in life.',WEST),
  q(LIFE,'Why do many older adults need vitamin B12 from fortified foods or supplements?','Less stomach acid makes food B12 hard to absorb',['B12 is destroyed by most medications','Older adults eat no foods that contain B12','The kidneys excrete B12 faster with age'],'A','Stomach acid and intrinsic factor are needed to release and absorb B12 from food. Both can decline with age, but the synthetic B12 in fortified foods is absorbed more easily.',ROTH),
  q(LIFE,'Which food is the greatest choking hazard for a 2-year-old if served as is?','Whole grapes',['Mashed banana','Cooked oatmeal','Shredded cheese'],'B','Round, firm foods such as whole grapes, hot dogs and nuts can block a toddler’s small airway. Grapes and hot dogs should be cut lengthwise into small pieces.',WEST),
  q(LIFE,'Why do women aged 19–50 need more iron (18 mg/day) than men of the same age (8 mg/day)?','To replace iron lost in menstruation',['Women absorb dietary iron less efficiently','Women have more muscle tissue','Estrogen destroys stored iron'],'D','Monthly blood loss means women of childbearing age lose more iron. After menopause, their requirement drops to the same 8 mg/day as men.',ROTH),
  q(DIG,'Where are most nutrients absorbed?','The small intestine',['The stomach','The large intestine','The liver'],'C','The small intestine’s villi and microvilli provide a huge surface area where most carbohydrates, proteins, fats, vitamins and minerals are absorbed.',ROTH),
  q(DIG,'What is the role of bile in digestion?','It emulsifies fats for enzymes to digest',['It digests proteins into amino acids','It neutralizes all the acid from the stomach','It absorbs water in the colon'],'A','Bile, made by the liver and stored in the gallbladder, breaks fat into small droplets. This increases the surface area for pancreatic lipase.',ROTH),
  q(DIG,'Chemical digestion of protein begins in which organ?','The stomach',['The mouth','The small intestine','The pancreas'],'B','Pepsin, activated by stomach acid, begins breaking proteins into smaller chains. Digestion is completed in the small intestine by pancreatic and intestinal enzymes.',ROTH),
  q(DIG,'Besides absorbing water and electrolytes, what does the large intestine contribute to nutrition?','Its bacteria make vitamin K and biotin',['It digests most dietary fat','It absorbs most dietary protein','It produces the bile used for fat digestion'],'D','Bacteria in the colon ferment fiber and produce vitamin K, biotin and short-chain fatty acids that nourish the colon lining.',ROTH),
  q(DIG,'For most people, which part of total daily energy expenditure is the largest?','Basal metabolic rate',['Physical activity','Thermic effect of food','Growth and repair'],'C','Basal metabolism, the energy used to keep the body alive at rest, makes up about 60–70% of daily energy use for most people. The thermic effect of food is only about 10%.',ROTH),
  q(CULT,'Under Jewish kosher dietary laws, which practice is followed?','Meat and dairy are not eaten together',['All seafood with scales is forbidden','Only vegetarian meals are eaten on weekends','Beef is never eaten'],'A','Kosher law separates meat and dairy, permits only certain animals slaughtered in a specific way, and allows fish only if they have fins and scales.',ROTH),
  q(CULT,'During the month of Ramadan, many Muslims:','Fast from dawn to sunset',['Eat only vegetarian meals','Avoid all foods containing added sugar','Eat one large meal at midday'],'B','During Ramadan, Muslims fast during daylight hours and eat before dawn and after sunset. Healthcare workers should plan medication and meal times around the fast.',ROTH),
  q(CULT,'Which dietary practice is common among people who follow Hinduism?','Avoiding beef',['Avoiding all grains during holy days','Eating only raw foods','Avoiding fruits with seeds'],'D','The cow is considered sacred in Hinduism, so beef is avoided, and many Hindus are vegetarian.',ROTH),
  q(ILL,'What is the key difference between a food allergy and a food intolerance?','A food allergy involves an immune system response',['A food intolerance is always more severe','A food allergy affects only the digestive tract','A food intolerance causes anaphylaxis'],'C','A food allergy is an immune (often IgE) reaction that can cause hives, swelling and anaphylaxis. An intolerance, such as lactose intolerance, is a digestive problem without an immune response.',ROTH),
  q(ILL,'Lactose intolerance causes bloating, gas and diarrhea after dairy because of a shortage of:','The enzyme lactase',['The enzyme lipase','Stomach acid','Bile salts'],'A','Without enough lactase, lactose is not broken down in the small intestine. Colon bacteria ferment it, producing gas and drawing water into the bowel.',ROTH),
  q(ILL,'A person with celiac disease must avoid which grains?','Wheat, barley and rye',['Rice, corn and millet','Oats only','Quinoa and buckwheat'],'B','Gluten in wheat, barley and rye triggers an immune reaction that damages the small intestine’s villi. Rice, corn, quinoa and buckwheat are naturally gluten-free.',ROTH),
  q(ILL,'In food safety, what is the temperature “danger zone” in which bacteria multiply fastest?','40–140 °F (4–60 °C)',['0–32 °F (−18–0 °C)','32–40 °F (0–4 °C)','140–212 °F (60–100 °C)'],'D','Bacteria grow rapidly between 40 °F and 140 °F. Cold foods should be kept at 40 °F or below and hot foods at 140 °F or above.',WEST),
  q(ILL,'Bulging or dented home-canned foods should be thrown out because they may contain which dangerous toxin-producing bacterium?','Clostridium botulinum',['Salmonella enteritidis','Escherichia coli','Staphylococcus aureus'],'C','C. botulinum grows without oxygen in improperly canned, low-acid foods and produces a toxin that can cause paralysis. Swelling of a can may signal gas from bacterial growth.',WEST),
  q(MNT,'In carbohydrate counting for diabetes, one carbohydrate choice contains about how many grams of carbohydrate?','15 g',['5 g','10 g','30 g'],'A','One carbohydrate choice equals about 15 g, such as one slice of bread or a small piece of fruit. Matching carbohydrate intake to insulin or activity helps control blood glucose.',ROTH),
  q(MNT,'A patient with chronic kidney disease who is not on dialysis is usually advised to limit which nutrients?','Potassium, phosphorus, sodium, protein',['Fiber, vitamin C, calcium and zinc','Carbohydrates and fluids only','Iron, folate, zinc and vitamin A'],'B','Failing kidneys cannot remove excess potassium, phosphorus, sodium or the waste from protein breakdown, so intake is controlled to slow the disease and prevent complications.',ROTH),
  q(MNT,'Which eating pattern was designed to lower blood pressure?','The DASH diet',['A ketogenic diet','A high-protein, low-fiber diet','A clear liquid diet'],'D','The DASH (Dietary Approaches to Stop Hypertension) diet emphasizes fruits, vegetables, whole grains and low-fat dairy and limits sodium, saturated fat and sweets.',WEST),
  q(MNT,'The Dietary Guidelines recommend limiting sodium to less than how much per day for most adults?','2,300 mg',['500 mg','1,000 mg','4,000 mg'],'C','The general limit is less than 2,300 mg of sodium per day, about one teaspoon of salt. Lower limits are often advised for people with hypertension.',WEST),
  q(MNT,'A patient with cancer has a poor appetite and is losing weight. Which strategy is most appropriate?','Small, frequent meals that are high in calories and protein',['Three large meals with mostly fruits and vegetables','A clear liquid diet until appetite returns','Skipping meals when nauseated, then eating more later'],'A','Cancer and its treatment can cause cachexia (wasting). Small, nutrient-dense meals and snacks are easier to tolerate and help maintain weight and strength.',ROTH),
  q(MNT,'Which diet is usually recommended to help prevent problems from diverticulosis?','A high-fiber diet',['A low-fiber, low-residue diet','A high-fat diet','A clear liquid diet'],'B','Fiber softens and adds bulk to stool, lowering pressure in the colon. During an acute diverticulitis flare, a low-fiber or liquid diet may be used temporarily.',ROTH),
  q(MNT,'A patient with dysphagia after a stroke is at risk of aspiration with thin liquids. Which diet change is typical?','Thickened liquids',['Carbonated drinks','Ice chips only','A high-fiber diet'],'D','Thickened liquids move more slowly, giving the patient time to close the airway while swallowing. A speech-language pathologist determines the right consistency.',ROTH),
  q(MNT,'Which item is allowed on a clear liquid diet?','Plain gelatin',['Milk','Orange juice with pulp','Cream soup'],'C','A clear liquid diet includes foods that are clear at room temperature and leave little residue, such as broth, gelatin, apple juice and tea. Milk and pulp are not clear liquids.',ROTH),
  q(MNT,'A patient receiving continuous tube feedings should have the head of the bed raised at least 30–45 degrees. Why?','To reduce the risk of aspiration',['To speed absorption of the formula','To prevent diarrhea','To keep the tube from clogging'],'A','Raising the head of the bed helps keep formula in the stomach and out of the lungs, preventing aspiration pneumonia.',ROTH),
  q(MNT,'A child with phenylketonuria (PKU) must avoid which sweetener?','Aspartame',['Sucrose','Stevia','Honey'],'B','In PKU, the body cannot break down the amino acid phenylalanine. Aspartame contains phenylalanine, so foods containing it carry a warning label.',ROTH)
 ],17)
};
